//! What UseDefs=0 changes in a SkyFrame, checked against the C library.
//!
//! `sky_use_defs_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_use_defs_probe.c`. The default Title leaves
//! out an Equinox or Epoch that has not been set (skyframe.c `GetTitle`),
//! and a conversion step that needs an Equinox, Epoch or observer position
//! that is not set is refused with AST__NOVAL, in the input SkyFrame for
//! the steps to the alignment system and in the output SkyFrame for the
//! steps from it (skyframe.c `VerifyMSMAttrs`).

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "sky_use_defs_oracle/cases.rs"]
mod cases;

use starlink_ast::error::ErrorCode;
use starlink_ast::frames::FrameSearch;
use starlink_ast::frames::{Frame, FrameRef, SkyFrame, SkySystem};

/// A SkyFrame with the probe's comma-separated settings.
fn sky(settings: &str) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    for s in settings.split(',') {
        match s.split_once('=').unwrap() {
            ("System", v) => f.set_system(SkySystem::parse(v).unwrap()),
            ("UseDefs", v) => f.set_use_defs(v == "1").unwrap(),
            ("Equinox", "J2010") => f.set_equinox_year(2010.0),
            ("Epoch", v) => f.set_epoch_year(v.parse().unwrap()),
            ("ObsLon", v) => {
                Frame::set_obs_lon(&mut f, v.parse::<f64>().unwrap().to_radians()).unwrap()
            }
            ("ObsLat", v) => {
                Frame::set_obs_lat(&mut f, v.parse::<f64>().unwrap().to_radians()).unwrap()
            }
            other => panic!("no Rust set-up for {other:?}"),
        }
    }
    f
}

#[test]
fn titles_match_the_c_library() {
    let mut failures = Vec::new();
    for &(settings, want) in cases::TITLES {
        let got = Frame::title(&sky(settings)).unwrap();
        if got != want {
            failures.push(format!("[{settings}]: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn conversions_match_the_c_library() {
    let mut failures = Vec::new();
    for &(target, template, want) in cases::CONVERSIONS {
        let got = match sky(target).find_frame_template(&sky(template), "") {
            Err(e) if e.code() == ErrorCode::Noval => Err("Noval"),
            Err(e) => panic!("[{target}] -> [{template}]: {e}"),
            Ok(None) => Ok(None),
            Ok(Some(fs)) => {
                let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
                let (x, y) = map.tran2(&[1.0], &[0.5], true).unwrap();
                Ok(Some([x[0], y[0]]))
            }
        };
        let same = match (&got, &want) {
            (Ok(Some(g)), Ok(Some(w))) => crate::common::c_values_eq(g, w),
            _ => got == want,
        };
        if !same {
            failures.push(format!(
                "[{target}] -> [{template}]: got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CONVERSIONS.len(),
        failures.join("\n")
    );
}

/// Picking axes from a SkyFrame with UseDefs=0 needs no Epoch or Equinox,
/// and the result keeps UseDefs=0, as in the C library (skyframe.c
/// `SubFrame`, checked with `astPickAxes` and an FK5 SkyFrame).
#[test]
fn picking_axes_is_exempt() {
    let f = sky("System=FK5,UseDefs=0");
    let (picked, _) = starlink_ast::frames::pick_axes(&f, &[2, 1]).unwrap();
    assert!(!picked.use_defs());
    assert!(picked.test_use_defs());
}
